  ownPasswordForm={current:'',next:'',confirm:''}; ownPasswordError=''; ownPasswordBusy=false;
  collectionEmployee:Agent|null=null; collectionCountryInput:string|null=null; readonly payoutCountries=['Zambia','South Africa','Tanzania','Kenya','Zimbabwe','Uganda','United Kingdom'];
  collectionTransfer:Transfer|null=null; selectedTransfer:Transfer|null=null; destinationCityInput=''; collectionReference=''; collectionQueue:Transfer[]=[]; private pollHandle:number|null=null;
  businessName=localStorage.getItem('shameen.businessName')||'Shameen Investments'; currency=localStorage.getItem('shameen.currency')||'USD';
  employeeForm={name:'',email:'',role:'Transfer agent',password:'',branchId:1};
  pageTitles:Record<string,string>={dashboard:'Overview',employee:'My desk',transactions:'Transfers',collections:'Payout queue',team:'Team & float',reports:'Daily reports',settings:'Settings'};
  get isAdmin(){return this.currentUser?.role==='Administrator'}
  get isSupervisor(){return this.currentUser?.role==='Supervisor'}
  get isManager(){return this.isAdmin||this.isSupervisor}
  get isCollectionAgent(){return !!this.currentUser?.collectionCountry}
  get userInitials(){return String(this.currentUser?.name||'SI').split(/\s+/).map((part:string)=>part[0]).join('').slice(0,2).toUpperCase()}
  get navItems(){const items=this.isManager?[{id:'dashboard',label:'Overview',icon:'▦'},{id:'transactions',label:'Transfers',icon:'↗'},{id:'reports',label:'Daily reports',icon:'◷'}]:[{id:'employee',label:'My desk',icon:'▦'},{id:'transactions',label:'My transfers',icon:'↗'}];return this.isCollectionAgent?[...items,{id:'collections',label:'Payout queue',icon:'✓'}]:items}
  get pageTitle(){return this.pageTitles[this.page]||'Overview'}
  get todayIso(){const now=new Date();return new Date(now.getTime()-now.getTimezoneOffset()*60000).toISOString().slice(0,10)}
  get selectedDateLabel(){return this.selectedDate===this.todayIso?'Today':new Intl.DateTimeFormat('en-ZA',{day:'numeric',month:'short',year:'numeric'}).format(new Date(this.selectedDate+'T12:00:00'))}
  get selectedBranchName(){return this.branches.find(b=>b.id===this.selectedBranchId)?.name||this.currentUser?.branchName||'Shameen Lusaka'}
  get selectedBranchCity(){return this.branches.find(b=>b.id===this.selectedBranchId)?.city||this.currentUser?.branchCity||'Lusaka'}
  get todayLabel(){return new Intl.DateTimeFormat('en-ZA',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date()).toUpperCase()}
  dayOpen=false;dayStarted='';openingFloat=0;floatInput:number|null=null;
  staff:Agent[]=[]; transfers:Transfer[]=[];
  destinationCityOptions:Record<string,string[]>={};
  form={customer:'',country:'Kenya',city:'',amount:null as number|null,method:'Cash pickup',employeeId:1};
  ngOnInit(){this.api.authStatus().subscribe({next:status=>{this.needsAdministratorSetup=status.needsAdministratorSetup;if(status.needsAdministratorSetup){this.authLoading=false;return}this.api.me().subscribe({next:user=>this.acceptUser(user),error:()=>{this.authLoading=false}})},error:()=>{this.authLoading=false;this.authError='Could not connect to the transfer service. Start the ASP.NET API and reload.'}})}
  ngOnDestroy(){if(this.pollHandle!==null)window.clearInterval(this.pollHandle)}
  get setupNameError(){return this.authSubmitted&&!this.authForm.name.trim()?'Enter your full name.':''}
  get setupEmailError(){if(!this.authSubmitted)return '';const email=this.authForm.email.trim();if(!email)return 'Enter an email address.';return /^\S+@\S+\.\S+$/.test(email)?'':'Enter a valid email address, such as name@company.com.'}
  get setupPasswordError(){if(!this.authSubmitted)return '';if(!this.authForm.password)return 'Enter a password.';return this.authForm.password.length<12?'Use at least 12 characters.':''}
  setupAdministrator(){if(this.authBusy)return;this.authSubmitted=true;this.authError='';this.authEmailServerError='';if(this.setupNameError||this.setupEmailError||this.setupPasswordError)return;this.authBusy=true;this.api.setupAdministrator(this.authForm).subscribe({next:()=>this.api.me().subscribe({next:user=>{this.authBusy=false;this.acceptUser(user)},error:()=>{this.authBusy=false;this.authError='Account created, but could not load the session. Please sign in.';this.needsAdministratorSetup=false}}),error:(error:any)=>{this.authBusy=false;const message=error.error?.message||error.error?.errors?.account?.[0]||'Could not create the administrator account.';if(message.toLowerCase().includes('email')&&message.toLowerCase().includes('use'))this.authEmailServerError=message;else this.authError=message}})}  submitLogin(){if(this.authBusy)return;this.authBusy=true;this.authError='';this.api.login({email:this.authForm.email,password:this.authForm.password}).subscribe({next:()=>this.api.me().subscribe({next:user=>{this.authBusy=false;this.acceptUser(user)},error:()=>{this.authBusy=false;this.authError='Sign in succeeded, but the account could not be loaded.'}}),error:()=>{this.authBusy=false;this.authError='Email or password is incorrect, or this account is inactive.'}})}
  acceptUser(user:any){this.currentUser=user;this.authLoading=false;this.page=this.isManager?'dashboard':(this.isCollectionAgent?'collections':'employee');if(this.pollHandle===null)this.pollHandle=window.setInterval(()=>this.refreshData(),30000);if(!this.isAdmin)this.selectedBranchId=user.branchId;this.api.getDestinationCities().subscribe({next:rows=>{this.destinationCityOptions=rows.reduce((groups,row)=>{(groups[row.country]??=[]).push(row.city);return groups},{} as Record<string,string[]>);if(!this.form.city&&this.selectedDestinationCities.length)this.form.city=this.selectedDestinationCities[0]},error:()=>this.showToast('Could not load destination cities.')});this.api.getBranches().subscribe({next:branches=>{this.branches=branches;if(!this.branches.some(b=>b.id===this.selectedBranchId))this.selectedBranchId=this.branches[0]?.id||user.branchId;this.refreshData()},error:()=>this.showToast('Could not load transfer locations from the API.')})}
